/** Human-facing GoodSale identifiers. Server defaults/constraints remain authoritative. */
function dateStamp(date = new Date()): string {
  return `${date.getFullYear()}${String(date.getMonth() + 1).padStart(2, '0')}${String(date.getDate()).padStart(2, '0')}`;
}

function digits(length: number): string {
  let value = '';
  for (let i = 0; i < length; i += 1) value += Math.floor(Math.random() * 10);
  return value;
}

/** GS-20261106-48291 */
export function makeOrderNumber(date = new Date()): string {
  return `GS-${dateStamp(date)}-${digits(5)}`;
}

/** GSD-829174620 — generated by the database; this is only for optimistic UI. */
export function makeShipmentTrackingId(): string {
  return `GSD-${digits(9)}`;
}

/** Groups every seller sub-order created by one checkout. */
export function makeCheckoutGroupId(date = new Date()): string {
  return `GSG-${dateStamp(date)}-${digits(5)}`;
}
